  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (327::BIGINT, 'Un buen profesor que da lecciones claras. Principalmente explica presentaciones muy largas, pero suelen ser claras con la información.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '5f8c5562811d14744b2e26dfc1226997363fa013f9f41d109bbc20459e616398'::TEXT, ARRAY[1030]::BIGINT[]),
    (327::BIGINT, 'Es un excelente profe, los quices son literalmente las presentaciones que hace en clase, aveces hace puntos extras en proyectos o quices sorpresa, sin comentarios negativos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '5e9323e9b976555bf49ae527c6f875adfea93c0705de92ceded758a0b75d09fd'::TEXT, ARRAY[1030]::BIGINT[]),
    (327::BIGINT, 'Explica muy bien, sus asignaciones van acorde a todo lo que enseña.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '74c4a629dd746091d3e26ba29180d14db11b629b57f809a027c75d2aafadb283'::TEXT, ARRAY[1030]::BIGINT[]),
    (327::BIGINT, 'Clases son aburridas pero los proyectos y exámenes son fáciles. Tuanis el profe.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra']::TEXT[], '2026-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'de6c86bc3739beb1e69435a022b0b1eb3efb2603412317bf9bc2b29ef5bac249'::TEXT, ARRAY[1030]::BIGINT[]),
    (327::BIGINT, 'No explica bien la materia, solo lee las presentaciones con más texto que la biblia. Los quices son sencillos, pero deja uno cada semana. Si pueden no lo lleven con él, no sabe de la materia solo se aferra a sus presentaciones.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2025-08-26T00:00:00+00:00'::TIMESTAMPTZ, '7d2fcb35bec364378944670b25d2e91c5513a8aa25092c3716046ccaa8e3665b'::TEXT, ARRAY[1032]::BIGINT[]),
    (327::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2025-08-12T00:00:00+00:00'::TIMESTAMPTZ, '30aec7765a0a20edf6ebf95bace5e4bded717746969f24e6dccd11e896576def'::TEXT, ARRAY[1017]::BIGINT[]),
    (327::BIGINT, 'EL MEJOR PROFE!! explica demasiado bien y es súper humilde, hace buenos chistes JAJAJAJAJA, no me aburro en su clase porque puedes platicar con él y preguntar si tienes alguna duda, todo te lo deja claro de manera sencilla.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-03-01T00:00:00+00:00'::TIMESTAMPTZ, 'a50cb47600c068ce6ba8b9203fe60fc5937d892b3bf0cb565800e26c5501557d'::TEXT, ARRAY[1017]::BIGINT[]),
    (327::BIGINT, 'Profe polémico. En otros cursos como FOC o arqui es excelente, en compi le cuesta se nota no maneja la materia 100% pero de fijo aprende más que con eddy o moraga. Con estudiar bastante para los quices y hacer bien los 2 proyectos vuela.Se aprende bastante con el proyecto pero hay q dedicarle tiempo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2025-01-21T00:00:00+00:00'::TIMESTAMPTZ, '1bf8e4490d30fcea91de49cd22207d715ce4af28ddff970a62918d111425c5ed'::TEXT, ARRAY[1054]::BIGINT[]),
    (327::BIGINT, 'Si estudian por aparte les va a ir bien y van a sentir los quices fáciles, las clases del profe no vale la pena ir si no hay entrega pero el mae ayuda mucho con dudas. Portafolios y tareas regalados. Muchos proyectos pero grupales y logrables. El mae es buena nota pero el curso es cansado.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-28T00:00:00+00:00'::TIMESTAMPTZ, '32f35571d72a575b90618549a3522b42257b63b2ef2128ad352d01f9150aeebc'::TEXT, ARRAY[1054]::BIGINT[]),
    (327::BIGINT, 'Mal profe pero muy buena persona, no es claro en las instrucciones de proyectos o laboratorios lo que lo vuelve algo complicado, también es confuso cuando explica, pero aclara dudas y no responde de mala manera. Vaya por buenas notas en los quizes/labs y la pasa fácil, la materia no es complicada.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos proyectos grupales']::TEXT[], '2024-12-04T00:00:00+00:00'::TIMESTAMPTZ, '08108348edce4a94ccf04d828d71c8d8688e2b86d5d38e62a4e825397ddabe6f'::TEXT, ARRAY[1032]::BIGINT[]),
    (327::BIGINT, 'El profe no se ve preparado a veces, además no es tan bueno explicando. Clases largas en las que lee presentaciones y deja muchas evaluaciones. Ponerle atención a las rúbricas porque es estricto con reclamos. Deja portafolios que ayudan al estudiante. Si le pone en los quices seguramente pasa.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2024-11-19T00:00:00+00:00'::TIMESTAMPTZ, '8052df6c7cfff6e08039481a99e707bb4a2cb905b45fa201674dc77d0c19d10d'::TEXT, ARRAY[1054]::BIGINT[]),
    (327::BIGINT, 'Muchas evaluaciones, es demasiado la carga. Es 0 flexible si pasa alguna eventualidad en alguna entrega. El Primer Proyecto tuvo 3 fases, además había un proyecto 2, entonces se sintieron 4 proyectos + 7 quices + 5 evaluaciones de bajo porcentaje + 2 tareas.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2024-11-19T00:00:00+00:00'::TIMESTAMPTZ, '28c0d0a5d9a0ede523947954a93eb9fa0d49243337798581e3afa23ef71e6998'::TEXT, ARRAY[1054]::BIGINT[]),
    (327::BIGINT, 'Sinceramente es de los mejores profes que he conocido de la carrera, llegué aquí escapando de los profes tan malos de la sede de Cartago y San José(Kirstein, Canessa) y la verdad es que fue la mejor decisión que pude tomar, no dude en matricular con él!!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, '6c4d6cdaecceea42f62c40ea513edbd577a8d14703c05f3bc77a8f15e7e78823'::TEXT, ARRAY[1017]::BIGINT[]),
    (327::BIGINT, 'Profundiza mucho la materia, hasta en cosas que no son importantes y eso es lo que mete a los quices que hay cada 15 dias. Los quices valen 50% de la nota y ahi es donde lo revienta a uno. No lo recomiendo si hay otro profesor que imparta el curso el curso.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-09-12T00:00:00+00:00'::TIMESTAMPTZ, '6c8d9a416c745522019f694cafed0d2da3c595f460742101e79abe7ae4ac0ae4'::TEXT, ARRAY[1054]::BIGINT[]),
    (327::BIGINT, 'Emmanuel? Goooooood'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2023-08-18T00:00:00+00:00'::TIMESTAMPTZ, '469208b0022c5aca1a07e1adf6befe1bf362c3bd53450b317f31a1431b1d977f'::TEXT, ARRAY[1017]::BIGINT[]),
    (327::BIGINT, 'No es mal profe, hay que hacer mucho estudio individual para todos los trabajos, en los quices sí basta con las clases. Los proyectos son pesadillos pero con salir regular en ambos proyectos y pasar los quices se logra, las clases sí son demasiado largas y aburridas pero cuesta que alguien se quede.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'dcf69b6245a37b0547a2c00fbc5782bf75d2fcc90a8cce97c7495e61167d98c9'::TEXT, ARRAY[1032]::BIGINT[]),
    (327::BIGINT, 'Sin duda el mejor profe para arqui, hace quices muy frecuentemente y da muy poco tiempo para hacerlos. Los labs y los proyectos no son fáciles asi que hay que ponerle bonito pero cae excelente'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Deja trabajos largos']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '206c42fa7224758ebe5007fe6634ba3d9a21e8666c5474fa23687b9d598e515a'::TEXT, ARRAY[1032]::BIGINT[]),
    (327::BIGINT, 'Buen profesor, para los proyectos si debe ser bastante habil en assembly, especificamente NASM y utiliza Ubuntu. Da tiempos extras y es comprensivo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo']::TEXT[], '2022-06-09T00:00:00+00:00'::TIMESTAMPTZ, '4d9f6849bac20e518ae248a38a307267589af399e28dd6cb1810887cc344ed12'::TEXT, ARRAY[1032]::BIGINT[]),
    (327::BIGINT, 'Los proyectos son un toque pesados pero poniéndole no deberían ser muy complicados de lograr, explica bien y da bastante apoyo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-08T00:00:00+00:00'::TIMESTAMPTZ, '0e2b48edfa64e58c79f5f19845b4d4bdd1ee2ad69a8f0cf054b8a35888391aac'::TEXT, ARRAY[1032]::BIGINT[]),
    (327::BIGINT, 'El profesor sabe de lo que habla y ayuda mucho cuando se le hace una pregunta. Los quices son casi que semanales, pero lo que se evalúa se ven ejemplos muy parecidos en clase, por lo que se hace muy sencillo. Muy recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-27T00:00:00+00:00'::TIMESTAMPTZ, '3acb7aa43b22c475fc1cf205f64532e42b5a1c9aad6081d31307e2bd45ab2826'::TEXT, ARRAY[1017]::BIGINT[]),
    (327::BIGINT, 'Muy buen profe, deja bastante trabajos y bastante quizes pero usted aprende haciendo y practicando'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '1da0534d5dbd53b5fca724f2efca644c8381be6f29cc1ad3dceeeed27f31f16c'::TEXT, ARRAY[1017]::BIGINT[]),
    (327::BIGINT, 'Es buen profe en casi todo diría yo, para mi lo malo fue que siento que hay detalles de la materia que no explica pero a la hora de evaluar si los evalúa y pues uno pierde algunos puntos. Deja susdebidos trabajos, en virtualidad no hace exámenes pero si bastante quices, solo es de ponerle.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-06-27T00:00:00+00:00'::TIMESTAMPTZ, '82fde61b6c597667172ca21e85de5d94efda7691ffc1811d71f851c772de3758'::TEXT, ARRAY[1017]::BIGINT[]),
    (327::BIGINT, 'Muy buen profe'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, 'c7b0230bfa4c53bc847d31df76b83538a944b889fd423b748dd0b1fb33b8aae6'::TEXT, ARRAY[1017]::BIGINT[]),
    (327::BIGINT, 'Excelente Profesor, recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Clases excelentes']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, '7095dffad37cdcbd4cabcab499368fbde13860384fa42a2d5a47af8d547772f8'::TEXT, ARRAY[1017]::BIGINT[]),
    (327::BIGINT, 'Los cursos son muy ligeros no siempre profundiza como debe, pero si pasar es un queque siempre que realize todas las actividades.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases largas']::TEXT[], '2020-11-25T00:00:00+00:00'::TIMESTAMPTZ, '8089f33af2e11332bff4dece8b970a2c41ce563a547d470777e57152a3ffeb1b'::TEXT, ARRAY[1054]::BIGINT[]),
    (327::BIGINT, 'Uno de los mejores profesores que he tenido en el TEC, súper claro la materia, se nota que sabe de lo que habla, con este profe aprendí haciendo, y no solo memorizando términos como es usual en el curso. Si quiere aprender, meta con él, él le explicará la materia que con otros no entendió'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-09-20T00:00:00+00:00'::TIMESTAMPTZ, '984a34ef68a6a00a60dd7079ce2929c0114b35c994e99c9135ac4863d18f5be6'::TEXT, ARRAY[1017]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
